#!/usr/bin/env python3
"""
Round 160b (culprits), 4 October 2026. Needs round 157k.

Adds a new basemap, Old fantasy painting.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 160b (4 October)\n\nNeeds round 157k (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Asked 4 October: a basemap in the manner of the fantasy card landscapes of\n  about 1993-2003 (acrylic and gouache on board, three depth layers, low\n  dusk light, muted slate, umber, moss, grey-violet and bone, loose far\n  brushwork, darkened corners, no camera effects). Only the manner is taken;\n  nothing is copied from any painting. Menu: "Old fantasy painting" (key\n  dusk), after Woodlands. One block ("Old fantasy painting, a seventh\n  basemap" to "end of Old fantasy painting"), layers outline-dusk-*\n  (DUSK_IDS), settings in DUSK.\n- Paint: the same Sentinel-2 picture as Woodlands (woodComposite) re-coloured\n  pixel by pixel (duskPaintPixels: moss for plants, umber to bone for bare\n  ground, slate for water, bone for snow, all dulled 28% toward grey-violet),\n  the board\'s faint grain, then loose strokes by woodStrokes with DUSK\'s own\n  broader brushes (duskpaint://, two helpers, duskWorkWith; main-thread\n  fallback). Detail falls off far out: wider washes below zoom 6\n  (DUSK.loose), the fine brush only from zoom 5 (DUSK.fineFrom).\n- Depth: high ground hazier with height (outline-dusk-haze: clear below\n  400 m, pale bone-violet by 4,000 m); a tilted view fades into pale fog and\n  the globe\'s edge into haze (DUSK.sky). Light: low dusk sun from 255\n  degrees at 12 degrees (multidirectional hillshade), grey-violet shadows,\n  dull bone light. Sea tinted slate by depth. Corners: #dusk-corners, one\n  see-through gradient just above the map canvas, under markers and boxes,\n  no clicks, hidden with the basemap or the hologram.\n- Closest zooms: Esri imagery moved 40% toward the palette, sharp\n  (duskphoto://, from 15.5 to 16.5), as Woodlands does.\n- Not carried: cloud banks, ruins, standing stones, a lone figure (nothing\n  is drawn that the picture does not show). Layer colours: bright.\n- Checked on made-up pictures in node; not seen against the live picture.\n']


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round160b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 157k" not in h.read_text(encoding="utf-8"):
        sys.exit("round160b: round 157k must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round160b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round160b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round160b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
